helpers:
inline bool kda_fwd_rank3(const std::string& layout) {
  return layout == "TND" || layout == "NTD";
}
inline bool kda_fwd_seq_major(const std::string& layout) {
  return layout == "BSND" || layout == "TND";
}
inline int64_t kda_fwd_tokens(const at::Tensor& q, const std::string& layout) {
  if (kda_fwd_rank3(layout)) {
    return kda_fwd_seq_major(layout) ? q.size(0) : q.size(1);
  }
  return kda_fwd_seq_major(layout) ? q.size(1) : q.size(2);
}
inline int64_t kda_fwd_vheads(const at::Tensor& v, const std::string& layout) {
  if (kda_fwd_rank3(layout)) {
    return kda_fwd_seq_major(layout) ? v.size(1) : v.size(0);
  }
  return kda_fwd_seq_major(layout) ? v.size(2) : v.size(1);
}
inline int64_t kda_fwd_batch(const at::Tensor& q, const std::string& layout) {
  return kda_fwd_rank3(layout) ? 1 : q.size(0);
}
inline int64_t kda_fwd_kdim(const at::Tensor& q, const std::string& layout) {
  return kda_fwd_rank3(layout) ? q.size(2) : q.size(3);
}
inline int64_t kda_fwd_vdim(const at::Tensor& v, const std::string& layout) {
  return kda_fwd_rank3(layout) ? v.size(2) : v.size(3);
}
inline int64_t kda_fwd_seq_num(const std::vector<int64_t>& cu_seqlens, int64_t batch) {
  return cu_seqlens.empty() ? batch : static_cast<int64_t>(cu_seqlens.size()) - 1;
}
inline int64_t kda_fwd_chunks(const std::vector<int64_t>& cu_seqlens, const std::vector<int64_t>& chunk_indices, int64_t chunk_size, int64_t tokens) {
  if (!chunk_indices.empty()) {
    return static_cast<int64_t>(chunk_indices.size()) / 2;
  }
  if (!cu_seqlens.empty()) {
    int64_t chunks = 0;
    for (size_t i = 0; i + 1 < cu_seqlens.size(); ++i) {
      const int64_t len = cu_seqlens[i + 1] - cu_seqlens[i];
      chunks += (len + chunk_size - 1) / chunk_size;
    }
    return chunks;
  }
  return (tokens + chunk_size - 1) / chunk_size;
}
inline std::vector<int64_t> kda_fwd_attn_sizes(const at::Tensor& q, const at::Tensor& v, const std::string& layout) {
  if (kda_fwd_rank3(layout)) {
    return {kda_fwd_tokens(q, layout), kda_fwd_vheads(v, layout), kda_fwd_vdim(v, layout)};
  }
  return {kda_fwd_batch(q, layout), kda_fwd_tokens(q, layout), kda_fwd_vheads(v, layout), kda_fwd_vdim(v, layout)};
}
inline std::vector<int64_t> kda_fwd_khead_sizes(const at::Tensor& q, const at::Tensor& v, const std::string& layout) {
  if (kda_fwd_rank3(layout)) {
    return {kda_fwd_vheads(v, layout), kda_fwd_tokens(q, layout), kda_fwd_kdim(q, layout)};
  }
  return {kda_fwd_batch(q, layout), kda_fwd_vheads(v, layout), kda_fwd_tokens(q, layout), kda_fwd_kdim(q, layout)};
}
inline std::vector<int64_t> kda_fwd_vhead_sizes(const at::Tensor& q, const at::Tensor& v, const std::string& layout) {
  if (kda_fwd_rank3(layout)) {
    return {kda_fwd_vheads(v, layout), kda_fwd_tokens(q, layout), kda_fwd_vdim(v, layout)};
  }
  return {kda_fwd_batch(q, layout), kda_fwd_vheads(v, layout), kda_fwd_tokens(q, layout), kda_fwd_vdim(v, layout)};
}
inline std::vector<int64_t> kda_fwd_matrix_sizes(const at::Tensor& q, const at::Tensor& v, const std::string& layout, int64_t chunk_size) {
  if (kda_fwd_rank3(layout)) {
    return {kda_fwd_vheads(v, layout), kda_fwd_tokens(q, layout), chunk_size};
  }
  return {kda_fwd_batch(q, layout), kda_fwd_vheads(v, layout), kda_fwd_tokens(q, layout), chunk_size};
}
inline std::vector<int64_t> kda_fwd_state_sizes(const at::Tensor& q, const at::Tensor& v, const std::string& layout, const std::vector<int64_t>& cu_seqlens, bool state_v_first) {
  return {kda_fwd_seq_num(cu_seqlens, kda_fwd_batch(q, layout)), kda_fwd_vheads(v, layout),
          state_v_first ? kda_fwd_vdim(v, layout) : kda_fwd_kdim(q, layout),
          state_v_first ? kda_fwd_kdim(q, layout) : kda_fwd_vdim(v, layout)};
}
inline std::vector<int64_t> kda_fwd_h_sizes(const at::Tensor& q, const at::Tensor& v, const std::string& layout, const std::vector<int64_t>& cu_seqlens, const std::vector<int64_t>& chunk_indices, int64_t chunk_size, bool state_v_first) {
  std::vector<int64_t> sizes;
  if (!kda_fwd_rank3(layout)) {
    sizes.push_back(kda_fwd_batch(q, layout));
  }
  sizes.push_back(kda_fwd_chunks(cu_seqlens, chunk_indices, chunk_size, kda_fwd_tokens(q, layout)));
  sizes.push_back(kda_fwd_vheads(v, layout));
  sizes.push_back(state_v_first ? kda_fwd_vdim(v, layout) : kda_fwd_kdim(q, layout));
  sizes.push_back(state_v_first ? kda_fwd_kdim(q, layout) : kda_fwd_vdim(v, layout));
  return sizes;
}
